1. /**
2.  * PoutineSubmission CRUD, the 5-active-submission cap, and Tag association logic
3.  * for the "Submit a poutine" experience (Phase 1).
4.  */
5. import {
6.   associateRows,
7.   createRow,
8.   deleteRow,
9.   disassociateRows,
10.   getRow,
11.   listRows,
12.   updateRow,
13.   uploadFileImage,
14.   type DataverseRow,
15. } from '../lib/dataverseClient';
16. import { createRestaurant } from './restaurants';
17. import {
18.   ACTIVE_SUBMISSION_STATUSES,
19.   ENTITY_SETS,
20.   MAX_ACTIVE_SUBMISSIONS,
21.   SUBMISSION_TAG_RELATIONSHIP,
22.   SubmissionStatus,
23.   type SubmissionStatusValue,
24. } from './constants';
25. import type { TagRow } from './tags';
26. 
27. export interface PoutineSubmissionRow {
28.   rpo_poutinesubmissionid: string;
29.   rpo_name: string;
30.   rpo_description: string | null;
31.   rpo_price: number | null;
32.   rpo_status: SubmissionStatusValue;
33.   restaurantId: string | null;
34.   restaurantName: string | null;
35.   createdOn: string | null;
36.   tags: TagRow[];
37.   /** Data-URL of the thumbnail-sized photo, when `rpo_photo` was selected and one exists. */
38.   photoDataUrl: string | null;
39. }
40. 
41. const SUBMISSION_SELECT = ['rpo_poutinesubmissionid', 'rpo_name', 'rpo_description', 'rpo_price', 'rpo_status', 'rpo_restaurantid', 'createdon'];
42. /**
43.  * Same as {@link SUBMISSION_SELECT} plus the `rpo_photo` image column. Dataverse
44.  * returns image columns as a base64-encoded thumbnail directly alongside other
45.  * selected fields on a normal retrieve (no separate download call needed) — see
46.  * "Use image column data in Microsoft Dataverse" in the Dataverse docs. Kept as a
47.  * separate select list so Phase 1's My Submissions view (which doesn't render a
48.  * photo) isn't forced to pay for the extra payload.
49.  */
50. const SUBMISSION_SELECT_WITH_PHOTO = [...SUBMISSION_SELECT, 'rpo_photo'];
51. const TAG_EXPAND = `${SUBMISSION_TAG_RELATIONSHIP}($select=rpo_tagid,rpo_name)`;
52. 
53. function escapeODataString(value: string): string {
54.   return value.replace(/'/g, "''");
55. }
56. 
57. function toSubmissionRow(row: DataverseRow): PoutineSubmissionRow {
58.   const restaurantName = row['_rpo_restaurantid_value@OData.Community.Display.V1.FormattedValue'] as
59.     | string
60.     | undefined;
61.   const relatedTags = (row[SUBMISSION_TAG_RELATIONSHIP] as DataverseRow[] | undefined) ?? [];
62.   const photo = row.rpo_photo as string | null | undefined;
63.   return {
64.     rpo_poutinesubmissionid: String(row.rpo_poutinesubmissionid),
65.     rpo_name: (row.rpo_name as string | undefined) ?? '',
66.     rpo_description: (row.rpo_description as string | null | undefined) ?? null,
67.     rpo_price: (row.rpo_price as number | null | undefined) ?? null,
68.     rpo_status: (row.rpo_status as SubmissionStatusValue | undefined) ?? SubmissionStatus.Draft,
69.     restaurantId: (row._rpo_restaurantid_value as string | null | undefined) ?? null,
70.     restaurantName: restaurantName ?? null,
71.     createdOn: (row.createdon as string | null | undefined) ?? null,
72.     tags: relatedTags.map((t) => ({ rpo_tagid: String(t.rpo_tagid), rpo_name: (t.rpo_name as string) ?? '' })),
73.     photoDataUrl: photo ? `data:image;base64,${photo}` : null,
74.   };
75. }
76. 
77. /** List all submissions created by the given SystemUser, newest first, including their tags. */
78. export async function listMySubmissions(submitterId: string): Promise<PoutineSubmissionRow[]> {
79.   const rows = await listRows(ENTITY_SETS.poutineSubmissions, {
80.     select: SUBMISSION_SELECT,
81.     filter: `_rpo_submitterid_value eq '${escapeODataString(submitterId)}'`,
82.     orderBy: ['createdon desc'],
83.     expand: TAG_EXPAND,
84.   });
85.   return rows.map(toSubmissionRow);
86. }
87. 
88. /**
89.  * List every submission visible in the public Browse feed — i.e. those that have
90.  * cleared moderation. Only `Approved` is a publicly-visible status: Draft/Submitted/
91.  * In Review are still going through the submitter's or moderator's workflow, and
92.  * Rejected never becomes public. Includes tags and the photo thumbnail (if any).
93.  */
94. export async function listApprovedSubmissions(): Promise<PoutineSubmissionRow[]> {
95.   const rows = await listRows(ENTITY_SETS.poutineSubmissions, {
96.     select: SUBMISSION_SELECT_WITH_PHOTO,
97.     filter: `rpo_status eq ${SubmissionStatus.Approved}`,
98.     orderBy: ['createdon desc'],
99.     expand: TAG_EXPAND,
100.   });
101.   return rows.map(toSubmissionRow);
102. }
103. 
104. /** Count how many of the submitter's submissions are in an "active" (cap-counting) status. */
105. export async function countActiveSubmissions(submitterId: string): Promise<number> {
106.   const statusFilter = ACTIVE_SUBMISSION_STATUSES.map((s) => `rpo_status eq ${s}`).join(' or ');
107.   const rows = await listRows(ENTITY_SETS.poutineSubmissions, {
108.     select: ['rpo_poutinesubmissionid'],
109.     filter: `_rpo_submitterid_value eq '${escapeODataString(submitterId)}' and (${statusFilter})`,
110.   });
111.   return rows.length;
112. }
113. 
114. export interface CreateSubmissionInput {
115.   submitterId: string;
116.   /** GUID of an existing restaurant, when the employee picked one from search results. */
117.   existingRestaurantId?: string;
118.   /** Required when existingRestaurantId is not provided. */
119.   newRestaurantName?: string;
120.   newRestaurantAddress?: string;
121.   name: string;
122.   description: string;
123.   price: number | null;
124.   status: typeof SubmissionStatus.Draft | typeof SubmissionStatus.Submitted;
125.   tagIds: string[];
126.   photo?: File;
127. }
128. 
129. /**
130.  * Creates a PoutineSubmission (creating its Restaurant first if a new one was entered),
131.  * associates the selected tags, and uploads the photo if one was provided.
132.  *
133.  * Callers must enforce the active-submission cap (via {@link countActiveSubmissions})
134.  * before calling this — it is not re-checked here to keep this function a single
135.  * atomic sequence of Dataverse calls.
136.  */
137. export async function createSubmission(input: CreateSubmissionInput): Promise<PoutineSubmissionRow> {
138.   let restaurantId = input.existingRestaurantId;
139.   if (!restaurantId) {
140.     if (!input.newRestaurantName?.trim() || !input.newRestaurantAddress?.trim()) {
141.       throw new Error('A restaurant name and address are required when no existing restaurant is selected.');
142.     }
143.     const restaurant = await createRestaurant(input.newRestaurantName, input.newRestaurantAddress);
144.     restaurantId = restaurant.rpo_restaurantid;
145.   }
146. 
147.   const created = await createRow(ENTITY_SETS.poutineSubmissions, {
148.     rpo_name: input.name.trim(),
149.     rpo_description: input.description.trim() || null,
150.     rpo_price: input.price,
151.     rpo_status: input.status,
152.     'rpo_restaurantid@odata.bind': `/${ENTITY_SETS.restaurants}(${restaurantId})`,
153.     'rpo_submitterid@odata.bind': `/${ENTITY_SETS.systemUsers}(${input.submitterId})`,
154.   });
155.   const submissionId = String(created.rpo_poutinesubmissionid);
156. 
157.   for (const tagId of input.tagIds) {
158.     await associateRows(
159.       ENTITY_SETS.poutineSubmissions,
160.       submissionId,
161.       SUBMISSION_TAG_RELATIONSHIP,
162.       ENTITY_SETS.tags,
163.       tagId,
164.     );
165.   }
166. 
167.   if (input.photo) {
168.     await uploadFileImage(ENTITY_SETS.poutineSubmissions, submissionId, 'rpo_photo', input.photo);
169.   }
170. 
171.   return getSubmission(submissionId);
172. }
173. 
174. /** Fetch a single submission (with its tags) by id. */
175. export async function getSubmission(submissionId: string): Promise<PoutineSubmissionRow> {
176.   const row = await getRow(ENTITY_SETS.poutineSubmissions, submissionId, [...SUBMISSION_SELECT]);
177.   // GetItem doesn't accept $expand in this connector op the way List does for our purposes here,
178.   // so tags are fetched separately and merged in.
179.   const tags = await getSubmissionTags(submissionId);
180.   return { ...toSubmissionRow(row), tags };
181. }
182. 
183. /** Same as {@link getSubmission}, but also includes the `rpo_photo` thumbnail — used by the Browse detail view. */
184. export async function getSubmissionWithPhoto(submissionId: string): Promise<PoutineSubmissionRow> {
185.   const row = await getRow(ENTITY_SETS.poutineSubmissions, submissionId, [...SUBMISSION_SELECT_WITH_PHOTO]);
186.   const tags = await getSubmissionTags(submissionId);
187.   return { ...toSubmissionRow(row), tags };
188. }
189. 
190. /** Fetch the tags currently associated with a submission. */
191. export async function getSubmissionTags(submissionId: string): Promise<TagRow[]> {
192.   const rows = await listRows(ENTITY_SETS.poutineSubmissions, {
193.     select: ['rpo_poutinesubmissionid'],
194.     filter: `rpo_poutinesubmissionid eq '${escapeODataString(submissionId)}'`,
195.     expand: TAG_EXPAND,
196.     top: 1,
197.   });
198.   const related = (rows[0]?.[SUBMISSION_TAG_RELATIONSHIP] as DataverseRow[] | undefined) ?? [];
199.   return related.map((t) => ({ rpo_tagid: String(t.rpo_tagid), rpo_name: (t.rpo_name as string) ?? '' }));
200. }
201. 
202. export interface UpdateSubmissionInput {
203.   name: string;
204.   description: string;
205.   price: number | null;
206.   status: SubmissionStatusValue;
207.   existingRestaurantId?: string;
208.   newRestaurantName?: string;
209.   newRestaurantAddress?: string;
210.   tagIds: string[];
211.   photo?: File;
212. }
213. 
214. /** Updates a Draft submission's fields, restaurant, tags (diffed), and optionally its photo. */
215. export async function updateSubmission(submissionId: string, input: UpdateSubmissionInput): Promise<PoutineSubmissionRow> {
216.   let restaurantId = input.existingRestaurantId;
217.   if (!restaurantId) {
218.     if (!input.newRestaurantName?.trim() || !input.newRestaurantAddress?.trim()) {
219.       throw new Error('A restaurant name and address are required when no existing restaurant is selected.');
220.     }
221.     const restaurant = await createRestaurant(input.newRestaurantName, input.newRestaurantAddress);
222.     restaurantId = restaurant.rpo_restaurantid;
223.   }
224. 
225.   await updateRow(ENTITY_SETS.poutineSubmissions, submissionId, {
226.     rpo_name: input.name.trim(),
227.     rpo_description: input.description.trim() || null,
228.     rpo_price: input.price,
229.     rpo_status: input.status,
230.     'rpo_restaurantid@odata.bind': `/${ENTITY_SETS.restaurants}(${restaurantId})`,
231.   });
232. 
233.   const currentTags = await getSubmissionTags(submissionId);
234.   const currentTagIds = new Set(currentTags.map((t) => t.rpo_tagid));
235.   const nextTagIds = new Set(input.tagIds);
236. 
237.   for (const tagId of nextTagIds) {
238.     if (!currentTagIds.has(tagId)) {
239.       await associateRows(ENTITY_SETS.poutineSubmissions, submissionId, SUBMISSION_TAG_RELATIONSHIP, ENTITY_SETS.tags, tagId);
240.     }
241.   }
242.   for (const tagId of currentTagIds) {
243.     if (!nextTagIds.has(tagId)) {
244.       await disassociateRows(ENTITY_SETS.poutineSubmissions, submissionId, SUBMISSION_TAG_RELATIONSHIP, ENTITY_SETS.tags, tagId);
245.     }
246.   }
247. 
248.   if (input.photo) {
249.     await uploadFileImage(ENTITY_SETS.poutineSubmissions, submissionId, 'rpo_photo', input.photo);
250.   }
251. 
252.   return getSubmission(submissionId);
253. }
254. 
255. /** Hard-deletes a submission. UI restricts this action to the employee's own Draft submissions. */
256. export async function withdrawSubmission(submissionId: string): Promise<void> {
257.   await deleteRow(ENTITY_SETS.poutineSubmissions, submissionId);
258. }
259. 
260. export { MAX_ACTIVE_SUBMISSIONS };
261.

1. /**
2.  * Restaurant lookup + find-or-create helpers used by the submission form so employees
3.  * can attach a new poutine to an existing Restaurant row instead of creating duplicates.
4.  */
5. import { createRow, getRow, listRows, type DataverseRow } from '../lib/dataverseClient';
6. import { ENTITY_SETS } from './constants';
7. 
8. export interface RestaurantRow {
9.   rpo_restaurantid: string;
10.   rpo_name: string;
11.   rpo_address?: string | null;
12. }
13. 
14. function toRestaurantRow(row: DataverseRow): RestaurantRow {
15.   return {
16.     rpo_restaurantid: String(row.rpo_restaurantid),
17.     rpo_name: (row.rpo_name as string | undefined) ?? '',
18.     rpo_address: (row.rpo_address as string | null | undefined) ?? null,
19.   };
20. }
21. 
22. function escapeODataString(value: string): string {
23.   return value.replace(/'/g, "''");
24. }
25. 
26. /** Search existing restaurants by (partial, case-insensitive) name match. */
27. export async function searchRestaurants(query: string, top = 8): Promise<RestaurantRow[]> {
28.   const trimmed = query.trim();
29.   if (!trimmed) return [];
30.   const rows = await listRows(ENTITY_SETS.restaurants, {
31.     select: ['rpo_restaurantid', 'rpo_name', 'rpo_address'],
32.     filter: `contains(rpo_name, '${escapeODataString(trimmed)}')`,
33.     orderBy: ['rpo_name asc'],
34.     top,
35.   });
36.   return rows.map(toRestaurantRow);
37. }
38. 
39. /** Creates a new Restaurant row. Latitude/longitude are left unset (populated later by a separate geocoding flow). */
40. export async function createRestaurant(name: string, address: string): Promise<RestaurantRow> {
41.   const created = await createRow(ENTITY_SETS.restaurants, {
42.     rpo_name: name.trim(),
43.     rpo_address: address.trim(),
44.   });
45.   return toRestaurantRow(created);
46. }
47. 
48. /** Fetch a single restaurant by id (used to pre-fill the picker when editing an existing submission). */
49. export async function getRestaurantById(restaurantId: string): Promise<RestaurantRow> {
50.   const row = await getRow(ENTITY_SETS.restaurants, restaurantId, ['rpo_restaurantid', 'rpo_name', 'rpo_address']);
51.   return toRestaurantRow(row);
52. }
53.

1. import { useEffect, useMemo, useState } from 'react';
2. import { EmptyState } from '../components/EmptyState/EmptyState';
3. import { BrowseFilters } from '../components/BrowseFilters/BrowseFilters';
4. import { PoutineCard } from '../components/PoutineCard/PoutineCard';
5. import { SubmissionDetail } from '../components/SubmissionDetail/SubmissionDetail';
6. import { listTags, type TagRow } from '../data/tags';
7. import { listApprovedSubmissions, type PoutineSubmissionRow } from '../data/submissions';
8. import { getAggregatesForSubmissions, type SubmissionAggregate } from '../data/feedback';
9. import './BrowseScreen.css';
10. 
11. type View = 'list' | 'detail';
12. 
13. /** Case-insensitive contains check for the poutine/restaurant name search. */
14. function matchesSearch(submission: PoutineSubmissionRow, query: string): boolean {
15.   if (!query) return true;
16.   const haystack = `${submission.rpo_name} ${submission.restaurantName ?? ''}`.toLowerCase();
17.   return haystack.includes(query.toLowerCase());
18. }
19. 
20. /** A submission matches the tag filter if it carries at least one of the selected tags. */
21. function matchesTags(submission: PoutineSubmissionRow, selectedTagIds: string[]): boolean {
22.   if (selectedTagIds.length === 0) return true;
23.   const submissionTagIds = new Set(submission.tags.map((t) => t.rpo_tagid));
24.   return selectedTagIds.some((id) => submissionTagIds.has(id));
25. }
26. 
27. /**
28.  * Phase 2 — the public discovery feed: approved poutines only, filterable by
29.  * tag and free-text (poutine/restaurant name), with a tap-through read-only
30.  * detail view. Filtering happens client-side after a single fetch of all
31.  * approved submissions, which is appropriate at this app's demo scale and
32.  * avoids fragile server-side OData filters across N:N tag relationships.
33.  */
34. export function BrowseScreen() {
35.   const [view, setView] = useState<View>('list');
36.   const [selectedSubmissionId, setSelectedSubmissionId] = useState<string | null>(null);
37. 
38.   const [submissions, setSubmissions] = useState<PoutineSubmissionRow[]>([]);
39.   const [tags, setTags] = useState<TagRow[]>([]);
40.   const [aggregates, setAggregates] = useState<Map<string, SubmissionAggregate>>(new Map());
41.   const [isLoading, setIsLoading] = useState(true);
42.   const [loadError, setLoadError] = useState<string | null>(null);
43. 
44.   const [searchText, setSearchText] = useState('');
45.   const [selectedTagIds, setSelectedTagIds] = useState<string[]>([]);
46. 
47.   useEffect(() => {
48.     let cancelled = false;
49.     async function load() {
50.       try {
51.         setIsLoading(true);
52.         setLoadError(null);
53.         const [approvedSubmissions, tagRows] = await Promise.all([listApprovedSubmissions(), listTags()]);
54.         if (cancelled) return;
55.         setSubmissions(approvedSubmissions);
56.         setTags(tagRows);
57.         const aggregateMap = await getAggregatesForSubmissions(
58.           approvedSubmissions.map((s) => s.rpo_poutinesubmissionid),
59.         );
60.         if (cancelled) return;
61.         setAggregates(aggregateMap);
62.       } catch (err) {
63.         if (!cancelled) setLoadError(err instanceof Error ? err.message : 'Failed to load the Browse feed.');
64.       } finally {
65.         if (!cancelled) setIsLoading(false);
66.       }
67.     }
68.     load();
69.     return () => {
70.       cancelled = true;
71.     };
72.   }, []);
73. 
74.   const filteredSubmissions = useMemo(
75.     () => submissions.filter((s) => matchesSearch(s, searchText) && matchesTags(s, selectedTagIds)),
76.     [submissions, searchText, selectedTagIds],
77.   );
78. 
79.   function handleSelect(submission: PoutineSubmissionRow) {
80.     setSelectedSubmissionId(submission.rpo_poutinesubmissionid);
81.     setView('detail');
82.   }
83. 
84.   function handleBack() {
85.     setSelectedSubmissionId(null);
86.     setView('list');
87.   }
88. 
89.   /**
90.    * Applies a single submission's freshly recomputed aggregate (from Phase 3's
91.    * Try/Review creation in SubmissionDetail) to the local aggregates map, so
92.    * the Browse feed reflects new tries/reviews without refetching every
93.    * submission or reloading the page.
94.    */
95.   function handleAggregateChange(changedSubmissionId: string, aggregate: SubmissionAggregate) {
96.     setAggregates((prev) => {
97.       const next = new Map(prev);
98.       next.set(changedSubmissionId, aggregate);
99.       return next;
100.     });
101.   }
102. 
103.   if (view === 'detail' && selectedSubmissionId) {
104.     return (
105.       <SubmissionDetail submissionId={selectedSubmissionId} onBack={handleBack} onAggregateChange={handleAggregateChange} />
106.     );
107.   }
108. 
109.   if (isLoading) {
110.     return <EmptyState eyebrow="Phase 2" title="Browse poutines" description="Loading approved poutines…" />;
111.   }
112. 
113.   if (loadError) {
114.     return <EmptyState eyebrow="Phase 2" title="Browse poutines" description={loadError} />;
115.   }
116. 
117.   return (
118.     <div className="browse-screen">
119.       <header className="browse-screen__header">
120.         <p className="browse-screen__eyebrow">Phase 2</p>
121.         <h1 className="browse-screen__title">Browse poutines</h1>
122.         <p className="browse-screen__count">
123.           {filteredSubmissions.length} of {submissions.length} approved poutines
124.         </p>
125.       </header>
126. 
127.       <BrowseFilters
128.         searchText={searchText}
129.         onSearchTextChange={setSearchText}
130.         tags={tags}
131.         selectedTagIds={selectedTagIds}
132.         onSelectedTagIdsChange={setSelectedTagIds}
133.       />
134. 
135.       {filteredSubmissions.length === 0 ? (
136.         <EmptyState
137.           title="No poutines match"
138.           description={
139.             submissions.length === 0
140.               ? 'No poutines have been approved yet — check back soon!'
141.               : 'Try clearing your search or tag filters.'
142.           }
143.         />
144.       ) : (
145.         <ul className="browse-screen__list">
146.           {filteredSubmissions.map((submission) => (
147.             <PoutineCard
148.               key={submission.rpo_poutinesubmissionid}
149.               submission={submission}
150.               aggregate={aggregates.get(submission.rpo_poutinesubmissionid)}
151.               onSelect={handleSelect}
152.             />
153.           ))}
154.         </ul>
155.       )}
156.     </div>
157.   );
158. }
159.

1. import { useEffect, useMemo, useState, type FormEvent } from 'react';
2. import { EmptyState } from '../EmptyState/EmptyState';
3. import type { RestaurantRow } from '../../data/restaurants';
4. import { getRestaurantById } from '../../data/restaurants';
5. import type { PoutineSubmissionRow } from '../../data/submissions';
6. import { getSubmissionWithPhoto } from '../../data/submissions';
7. import {
8.   aggregateFromFeedback,
9.   getFeedbackForSubmission,
10.   type SubmissionAggregate,
11.   type SubmissionFeedback,
12. } from '../../data/feedback';
13. import { createTry, getTryForEmployee } from '../../data/tries';
14. import { createReview, getReviewForTryAndReviewer } from '../../data/reviews';
15. import { getCurrentUser, type CurrentUser } from '../../data/currentUser';
16. import '../TagMultiSelect/TagMultiSelect.css';
17. import '../StatusBadge/StatusBadge.css';
18. import './SubmissionDetail.css';
19. 
20. interface SubmissionDetailProps {
21.   submissionId: string;
22.   onBack: () => void;
23.   /**
24.    * Called after a Try or Review is successfully created, with the freshly
25.    * recomputed aggregate for this submission — lets the Browse feed
26.    * (BrowseScreen) update this poutine's card without refetching or reloading
27.    * the whole list.
28.    */
29.   onAggregateChange?: (submissionId: string, aggregate: SubmissionAggregate) => void;
30. }
31. 
32. function formatPrice(price: number | null): string {
33.   return price === null ? '\u2014' : `$${price.toFixed(2)}`;
34. }
35. 
36. function formatDate(value: string | null): string {
37.   if (!value) return '';
38.   return new Date(value).toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
39. }
40. 
41. /**
42.  * Detail view for one approved poutine: full submission info, restaurant
43.  * details, tags, existing Tries/Reviews, and (Phase 3) the signed-in
44.  * employee's own "Log a try" / "Leave a review" actions.
45.  */
46. export function SubmissionDetail({ submissionId, onBack, onAggregateChange }: SubmissionDetailProps) {
47.   const [submission, setSubmission] = useState<PoutineSubmissionRow | null>(null);
48.   const [restaurant, setRestaurant] = useState<RestaurantRow | null>(null);
49.   const [feedback, setFeedback] = useState<SubmissionFeedback | null>(null);
50.   const [currentUser, setCurrentUser] = useState<CurrentUser | null>(null);
51.   const [isLoading, setIsLoading] = useState(true);
52.   const [loadError, setLoadError] = useState<string | null>(null);
53. 
54.   const [isLoggingTry, setIsLoggingTry] = useState(false);
55.   const [showReviewForm, setShowReviewForm] = useState(false);
56.   const [rating, setRating] = useState(0);
57.   const [comment, setComment] = useState('');
58.   const [isSubmittingReview, setIsSubmittingReview] = useState(false);
59.   const [actionError, setActionError] = useState<string | null>(null);
60. 
61.   useEffect(() => {
62.     let cancelled = false;
63.     async function load() {
64.       try {
65.         setIsLoading(true);
66.         setLoadError(null);
67.         const sub = await getSubmissionWithPhoto(submissionId);
68.         if (cancelled) return;
69.         setSubmission(sub);
70.         const [restaurantRow, feedbackData, user] = await Promise.all([
71.           sub.restaurantId ? getRestaurantById(sub.restaurantId) : Promise.resolve(null),
72.           getFeedbackForSubmission(submissionId),
73.           getCurrentUser(),
74.         ]);
75.         if (cancelled) return;
76.         setRestaurant(restaurantRow);
77.         setFeedback(feedbackData);
78.         setCurrentUser(user);
79.       } catch (err) {
80.         if (!cancelled) setLoadError(err instanceof Error ? err.message : 'Failed to load this poutine.');
81.       } finally {
82.         if (!cancelled) setIsLoading(false);
83.       }
84.     }
85.     load();
86.     return () => {
87.       cancelled = true;
88.     };
89.   }, [submissionId]);
90. 
91.   const myTry = useMemo(() => {
92.     if (!feedback || !currentUser) return null;
93.     return feedback.tries.find((t) => t.employeeId === currentUser.systemUserId) ?? null;
94.   }, [feedback, currentUser]);
95. 
96.   const myReview = useMemo(() => {
97.     if (!feedback || !currentUser || !myTry) return null;
98.     return feedback.reviews.find((r) => r.tryId === myTry.rpo_tryid && r.reviewerId === currentUser.systemUserId) ?? null;
99.   }, [feedback, currentUser, myTry]);
100. 
101.   /** Re-fetches Tries/Reviews for this submission and propagates the recomputed aggregate upward. */
102.   async function refreshFeedback() {
103.     const updated = await getFeedbackForSubmission(submissionId);
104.     setFeedback(updated);
105.     onAggregateChange?.(submissionId, aggregateFromFeedback(updated));
106.   }
107. 
108.   async function handleLogTry() {
109.     if (!currentUser) return;
110.     setActionError(null);
111.     setIsLoggingTry(true);
112.     try {
113.       // Race guard: re-check right before creating, in case of a double-click or a
114.       // Try logged from another tab/session since this view loaded.
115.       const existing = await getTryForEmployee(submissionId, currentUser.systemUserId);
116.       if (!existing) {
117.         await createTry({ submissionId, employeeId: currentUser.systemUserId });
118.       }
119.       await refreshFeedback();
120.     } catch (err) {
121.       setActionError(err instanceof Error ? err.message : 'Failed to log your try.');
122.     } finally {
123.       setIsLoggingTry(false);
124.     }
125.   }
126. 
127.   async function handleSubmitReview(e: FormEvent) {
128.     e.preventDefault();
129.     if (!currentUser || !myTry) return;
130.     if (rating < 1 || rating > 5) {
131.       setActionError('Please choose a star rating from 1 to 5.');
132.       return;
133.     }
134.     setActionError(null);
135.     setIsSubmittingReview(true);
136.     try {
137.       // Race guard: one review per employee per poutine (see memory-bank.md's
138.       // Phase 3 decision) — re-check right before creating.
139.       const existing = await getReviewForTryAndReviewer(myTry.rpo_tryid, currentUser.systemUserId);
140.       if (existing) {
141.         setActionError("You've already reviewed this poutine.");
142.         return;
143.       }
144.       await createReview({
145.         tryId: myTry.rpo_tryid,
146.         reviewerId: currentUser.systemUserId,
147.         starRating: rating,
148.         comment: comment.trim() || null,
149.       });
150.       setShowReviewForm(false);
151.       setRating(0);
152.       setComment('');
153.       await refreshFeedback();
154.     } catch (err) {
155.       setActionError(err instanceof Error ? err.message : 'Failed to submit your review.');
156.     } finally {
157.       setIsSubmittingReview(false);
158.     }
159.   }
160. 
161.   if (isLoading) {
162.     return <EmptyState title="Loading" description="Loading this poutine…" />;
163.   }
164. 
165.   if (loadError || !submission) {
166.     return <EmptyState title="Couldn't load this poutine" description={loadError ?? 'Unknown error.'} />;
167.   }
168. 
169.   return (
170.     <div className="submission-detail">
171.       <button type="button" className="btn btn--secondary btn--small submission-detail__back" onClick={onBack}>
172.         {'\u2190'} Back to Browse
173.       </button>
174. 
175.       <div className="submission-detail__card">
176.         {submission.photoDataUrl && (
177.           <img className="submission-detail__photo" src={submission.photoDataUrl} alt={submission.rpo_name} />
178.         )}
179. 
180.         <h1 className="submission-detail__title">{submission.rpo_name}</h1>
181.         {restaurant && <p className="submission-detail__restaurant">{restaurant.rpo_name}</p>}
182.         {restaurant?.rpo_address && <p className="submission-detail__address">{restaurant.rpo_address}</p>}
183.         <p className="submission-detail__meta">{formatPrice(submission.rpo_price)}</p>
184. 
185.         {submission.tags.length > 0 && (
186.           <div className="submission-detail__tags">
187.             {submission.tags.map((tag) => (
188.               <span key={tag.rpo_tagid} className="tag-chip">
189.                 {tag.rpo_name}
190.               </span>
191.             ))}
192.           </div>
193.         )}
194. 
195.         {submission.rpo_description && <p className="submission-detail__description">{submission.rpo_description}</p>}
196.       </div>
197. 
198.       <section className="submission-detail__actions">
199.         {actionError && <p className="form-field__error">{actionError}</p>}
200. 
201.         {!myTry && (
202.           <button type="button" className="btn btn--primary" onClick={handleLogTry} disabled={isLoggingTry}>
203.             {isLoggingTry ? 'Logging…' : "I've tried this!"}
204.           </button>
205.         )}
206. 
207.         {myTry && !myReview && !showReviewForm && (
208.           <div className="submission-detail__action-row">
209.             <span className="status-badge status-badge--tried">
210.               Tried{myTry.triedOn ? ` on ${formatDate(myTry.triedOn)}` : ''}
211.             </span>
212.             <button type="button" className="btn btn--secondary btn--small" onClick={() => setShowReviewForm(true)}>
213.               Leave a review
214.             </button>
215.           </div>
216.         )}
217. 
218.         {myTry && myReview && (
219.           <span className="status-badge status-badge--tried">
220.             You reviewed this {'\u2605'.repeat(myReview.starRating)}
221.           </span>
222.         )}
223. 
224.         {showReviewForm && (
225.           <form className="submission-detail__review-form" onSubmit={handleSubmitReview}>
226.             <div className="form-field">
227.               <span className="form-field__label">Your rating</span>
228.               <div className="submission-detail__star-picker" role="radiogroup" aria-label="Star rating">
229.                 {[1, 2, 3, 4, 5].map((n) => (
230.                   <button
231.                     key={n}
232.                     type="button"
233.                     className={`submission-detail__star-btn${
234.                       n <= rating ? ' submission-detail__star-btn--filled' : ''
235.                     }`}
236.                     role="radio"
237.                     aria-checked={n === rating}
238.                     aria-label={`${n} star${n === 1 ? '' : 's'}`}
239.                     onClick={() => setRating(n)}
240.                   >
241.                     {'\u2605'}
242.                   </button>
243.                 ))}
244.               </div>
245.             </div>
246.             <div className="form-field">
247.               <label className="form-field__label" htmlFor="submission-detail-review-comment">
248.                 Comment (optional)
249.               </label>
250.               <textarea
251.                 id="submission-detail-review-comment"
252.                 className="form-field__textarea"
253.                 value={comment}
254.                 onChange={(e) => setComment(e.target.value)}
255.                 placeholder="What did you think?"
256.               />
257.             </div>
258.             <div className="form-actions">
259.               <button type="submit" className="btn btn--primary btn--small" disabled={isSubmittingReview || rating === 0}>
260.                 {isSubmittingReview ? 'Submitting…' : 'Submit review'}
261.               </button>
262.               <button
263.                 type="button"
264.                 className="btn btn--secondary btn--small"
265.                 onClick={() => {
266.                   setShowReviewForm(false);
267.                   setActionError(null);
268.                   setRating(0);
269.                   setComment('');
270.                 }}
271.               >
272.                 Cancel
273.               </button>
274.             </div>
275.           </form>
276.         )}
277.       </section>
278. 
279.       <section className="submission-detail__feedback">
280.         <h2 className="submission-detail__section-title">
281.           Tries {feedback ? `(${feedback.tries.length})` : ''}
282.         </h2>
283.         {!feedback || feedback.tries.length === 0 ? (
284.           <p className="submission-detail__empty">No one has tried this poutine yet.</p>
285.         ) : (
286.           <ul className="submission-detail__try-list">
287.             {feedback.tries.map((t) => (
288.               <li key={t.rpo_tryid} className="submission-detail__try-item">
289.                 {t.employeeName ?? 'An employee'} tried this{t.triedOn ? ` on ${formatDate(t.triedOn)}` : ''}
290.               </li>
291.             ))}
292.           </ul>
293.         )}
294. 
295.         <h2 className="submission-detail__section-title">
296.           Reviews {feedback ? `(${feedback.reviews.length})` : ''}
297.         </h2>
298.         {!feedback || feedback.reviews.length === 0 ? (
299.           <p className="submission-detail__empty">No reviews yet.</p>
300.         ) : (
301.           <ul className="submission-detail__review-list">
302.             {feedback.reviews.map((r) => (
303.               <li key={r.rpo_reviewid} className="submission-detail__review-item">
304.                 <div className="submission-detail__review-header">
305.                   <span className="submission-detail__review-rating">{'\u2605'.repeat(r.starRating)}</span>
306.                   <span className="submission-detail__review-author">{r.reviewerName ?? 'An employee'}</span>
307.                   {r.createdOn && <span className="submission-detail__review-date">{formatDate(r.createdOn)}</span>}
308.                 </div>
309.                 {r.comment && <p className="submission-detail__review-comment">{r.comment}</p>}
310.               </li>
311.             ))}
312.           </ul>
313.         )}
314.       </section>
315.     </div>
316.   );
317. }
