1. /*
2.  * Design tokens for the Poutine League "Comptoir Championship" system.
3.  * Source of truth: code-apps/DESIGN.md (shared across employee + admin apps).
4.  * Do not hand-roll one-off colors/spacing in components — reference these
5.  * custom properties so both apps stay visually consistent.
6.  */
7. :root {
8.   /* Colors */
9.   --color-fry-gold: #d99a2b;
10.   --color-fry-gold-deep: #b87a1c;
11.   --color-ketchup-red: #c23b2e;
12.   --color-ketchup-red-deep: #9c2b21;
13.   --color-relish-green: #5c7a3a;
14.   --color-mustard-amber: #e0a419;
15.   --color-cream-counter: #fbf3e6;
16.   --color-paper-white: #fffdf8;
17.   --color-checker-light: #edd9b8;
18.   --color-gravy-ink: #2a1d14;
19.   --color-gravy-text: #3a2a1e;
20.   --color-gravy-text-soft: #6b5644;
21. 
22.   /* Typography */
23.   --font-display: "Alfa Slab One", Georgia, serif;
24.   --font-body: "Inter", system-ui, sans-serif;
25.   --font-score: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
26. 
27.   --text-display-size: clamp(2.25rem, 5vw, 3.75rem);
28.   --text-display-weight: 400;
29.   --text-display-line-height: 1.05;
30.   --text-display-letter-spacing: -0.01em;
31. 
32.   --text-headline-size: clamp(1.5rem, 3vw, 2.25rem);
33.   --text-headline-weight: 400;
34.   --text-headline-line-height: 1.1;
35. 
36.   --text-title-size: 1.25rem;
37.   --text-title-weight: 700;
38.   --text-title-line-height: 1.3;
39. 
40.   --text-body-size: 1rem;
41.   --text-body-weight: 400;
42.   --text-body-line-height: 1.5;
43. 
44.   --text-label-size: 0.8125rem;
45.   --text-label-weight: 600;
46.   --text-label-line-height: 1.2;
47.   --text-label-letter-spacing: 0.02em;
48. 
49.   --text-score-size: 1.125rem;
50.   --text-score-weight: 700;
51.   --text-score-line-height: 1;
52. 
53.   /* Radii */
54.   --radius-sm: 6px;
55.   --radius-md: 12px;
56.   --radius-lg: 20px;
57.   --radius-pill: 999px;
58. 
59.   /* Spacing */
60.   --space-xs: 4px;
61.   --space-sm: 8px;
62.   --space-md: 16px;
63.   --space-lg: 24px;
64.   --space-xl: 40px;
65. 
66.   /* Shadows ("sticker" — hard offset, zero blur) */
67.   --shadow-sticker: 3px 3px 0 var(--color-gravy-ink);
68.   --shadow-sticker-pressed: 1px 1px 0 var(--color-gravy-ink);
69.   --shadow-sticker-lifted: 5px 5px 0 var(--color-gravy-ink);
70. 
71.   /* Layout */
72.   --layout-max-width: 1200px;
73.   --nav-sidebar-width: 240px;
74.   --nav-bottom-height: 64px;
75. }
