.map-screen {
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
  max-width: var(--layout-max-width);
}

.map-screen__eyebrow {
  font-family: var(--font-body);
  font-size: var(--text-label-size);
  font-weight: var(--text-label-weight);
  letter-spacing: var(--text-label-letter-spacing);
  text-transform: uppercase;
  color: var(--color-gravy-text-soft);
}

.map-screen__title {
  font-family: var(--font-headline, var(--font-display));
  font-size: var(--text-headline-size);
  font-weight: var(--text-headline-weight);
  line-height: var(--text-headline-line-height);
  color: var(--color-gravy-text);
  margin: var(--space-xs) 0;
}

.map-screen__count {
  font-family: var(--font-body);
  font-size: var(--text-body-size);
  color: var(--color-gravy-text-soft);
}

.map-screen__map-wrap {
  width: 100%;
  height: 60vh;
  min-height: 360px;
  border: 2px solid var(--color-gravy-ink);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sticker);
  overflow: hidden;
}

.map-screen__map {
  width: 100%;
  height: 100%;
}

.map-screen__ungeocoded-notice {
  font-family: var(--font-body);
  font-size: var(--text-label-size);
  color: var(--color-gravy-text-soft);
  background-color: var(--color-checker-light);
  border: 2px solid var(--color-gravy-ink);
  border-radius: var(--radius-md);
  padding: var(--space-sm) var(--space-md);
}

/*
 * Custom fry-gold circular pin (divIcon, no image assets) matching DESIGN.md's
 * "Map pins: circular fry-gold-filled pins with gravy-ink border matching the
 * rank-badge shape language" rule.
 */
.map-pin-icon {
  background: transparent;
  border: none;
}

.map-pin-icon__dot {
  display: block;
  width: 24px;
  height: 24px;
  background-color: var(--color-fry-gold);
  border: 2px solid var(--color-gravy-ink);
  border-radius: 50%;
  box-shadow: var(--shadow-sticker);
}

/*
 * Leaflet popup re-themed to match the "card-poutine" / sticker-shadow
 * language (flat, hard-offset shadow, ink border, paper-white surface) —
 * these overrides target Leaflet's own generated class names since the
 * library doesn't expose a themable popup component.
 */
.leaflet-popup-content-wrapper {
  background-color: var(--color-paper-white);
  border: 2px solid var(--color-gravy-ink);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sticker);
}

.leaflet-popup-content {
  margin: var(--space-sm) var(--space-md);
}

.leaflet-popup-tip {
  background-color: var(--color-paper-white);
  border: 2px solid var(--color-gravy-ink);
